package diameter

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// iana.json is generated by tools/gendata from the IANA AAA Parameters registry.
//
//go:embed iana.json
var ianaJSON []byte

type ianaEntry struct {
	Code uint32 `json:"code"`
	Name string `json:"name"`
	Ref  string `json:"ref"`
}

type ianaData struct {
	Source       string      `json:"source"`
	Results      []ianaEntry `json:"results"`
	Applications []ianaEntry `json:"applications"`
}

type ianaIndex struct {
	source       string
	results      map[uint32]string
	applications map[uint32]string
}

var iana = sync.OnceValue(func() ianaIndex {
	var d ianaData
	if err := json.Unmarshal(ianaJSON, &d); err != nil {
		panic("diameter: embedded iana.json: " + err.Error())
	}
	idx := ianaIndex{source: d.Source, results: map[uint32]string{}, applications: map[uint32]string{}}
	for _, e := range d.Results {
		idx.results[e.Code] = e.Name
	}
	for _, e := range d.Applications {
		idx.applications[e.Code] = e.Name
	}
	return idx
})

// ResultName is the IANA name of a Result-Code, or "" when the code is not assigned.
func ResultName(code uint32) string {
	return iana().results[code]
}

// ApplicationName is the IANA name of a Diameter application id, or "" when the id is not assigned.
func ApplicationName(id uint32) string {
	return iana().applications[id]
}

// IANASource says which registry version the names come from.
func IANASource() string {
	return iana().source
}

// IsSuccess reports whether a Result-Code is in the Success class (2xxx).
func IsSuccess(code uint32) bool {
	return code >= 2000 && code < 3000
}
